/** S151L001.B05PROCESOS: consulta y actualización del registro de procesos B05. */
public interface ControlProcesosClient {
    /** Función 1: consulta el proceso activo de un paso. Vacío si el resultado no es 0. */
    Optional<ProcesoB05> consultaProceso(int sistema, int paso);
}

/** CTLVERS.DAME_TIT: resuelve el título vigente de una librería por su identificador. */
public interface ControlVersionesClient {
    Optional<String> titulo(String identificador);
}

/** EA_ARR_B05: buffer EBCDIC de 501 posiciones; campos numéricos en display. */
public record ProcesoB05(
        int funcion,        // [00] 2
        int sistema,        // [02] 4
        int fechaProceso,   // [06] 8  AAAAMMDD
        int numProceso,     // [14] 4  paso
        int statusPrograma, // [18] 2
        long mix,           // [24] 8  número de mix del proceso en MCP
        int fechaInicio,    // [32] 8
        int horaInicio,     // [40] 6
        int fechaFin,       // [46] 8
        int horaFin,        // [54] 6
        long regInicio,     // [60] 8
        long regFin) {      // [68] 8

    static ProcesoB05 desde(byte[] ebcdic) {
        String s = new String(ebcdic, Charset.forName("IBM037"));
        return new ProcesoB05(num(s, 0, 2), num(s, 2, 4), num(s, 6, 8), num(s, 14, 4),
                num(s, 18, 2), lnum(s, 24, 8), num(s, 32, 8), num(s, 40, 6),
                num(s, 46, 8), num(s, 54, 6), lnum(s, 60, 8), lnum(s, 68, 8));
    }
}

/** PROCEDURE VERSIONES. */
void resuelveLibreriaControl() {
    Optional<String> titulo = versiones.titulo(props.idLibreriaControl());   // "S151L001CTL"
    if (titulo.isEmpty()) {
        // El fuente solo despliega el error y sigue con el título por omisión de S151L001.
        log.error("ERROR EN CONTROL DE VERSIONES NO EXISTE LIBRERIA");
        if (props.abortarSinVersion()) {
            throw new ControlVersionesException(props.idLibreriaControl());
        }
    }
}

/** APLICA_HI, primera parte: función 1, sistema, fecha 0 y paso. */
private Optional<Long> mixDelPaso(int sistema, int paso) {
    Optional<ProcesoB05> p = control.consultaProceso(sistema, paso);   // B05PROCESOS(EA_ARR_B05)
    if (p.isEmpty()) {
        log.warn("Paso {} de S{} sin proceso activo en B05: no se envía HI", paso, sistema);
    }
    return p.map(ProcesoB05::mix);                                      // IDFB05MIX
}

/** APLICA_HI, segunda parte: "{mix} HI {n}" por la consola del sistema. */
private void enviaHi(long mix, int valor) {
    if (mix > 9999) {
        // REPLACE ... I_MEZCLA FOR 4 DIGITS conserva solo los cuatro dígitos de menor orden
        throw new MixFueraDeRangoException(mix);
    }
    String comando = "%04d HI %04d".formatted(mix, valor);
    RespuestaConsola r = consola.ejecuta(comando);   // DCKEYIN(POINTER(A_COMANDO), A_RESPUESTA)
    log.info("{} -> {}", comando, r.texto());        // el fuente no lee A_RESPUESTA
}

@Component
@RequiredArgsConstructor
public class CierreS500Tasklet implements Tasklet {

    private final P021Properties props;     // sistema 500, pasos [9, 12, 2], espera PT300S

    @Override
    public RepeatStatus execute(StepContribution sc, ChunkContext cc) throws InterruptedException {
        resuelveLibreriaControl();                          // VERSIONES
        for (int ronda = 1; ronda <= 2; ronda++) {
            for (int paso : props.pasos()) {                // orden fijo: 9, 12, 2
                mixDelPaso(props.sistema(), paso).ifPresent(mix -> enviaHi(mix, 1));
            }
            if (ronda == 1) {
                Thread.sleep(props.espera().toMillis());    // WAIT((300)): sin verificar respuesta
            }
        }
        return RepeatStatus.FINISHED;
    }
}

